import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

public class Main {
  public static void main(String[] args) throws Exception {
      Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/mibase", "user", "pass");
      Statement stmt = conn.createStatement();

      String sql = "SELECT usuarios.nombre AS us_nombre, productos.nombre AS pr_nombre " +
                   "FROM usuarios INNER JOIN productos ON usuarios.id = productos.usuario_id";

      ResultSet rs = stmt.executeQuery(sql);
      while (rs.next()) {
          System.out.println(rs.getString("us_nombre") + " - " + rs.getString("pr_nombre"));
      }
  }
}
